import { WebPlugin } from '@capacitor/core';
import type { AppExitReasonPlugin, LastExitReasonsResult, ResourceSnapshot } from './definitions';

export class AppExitReasonWeb extends WebPlugin implements AppExitReasonPlugin {
  async getLastExitReasons(): Promise<LastExitReasonsResult> {
    return { supported: false, platform: 'web', aggregated: false, reasons: [] };
  }

  async getResourceSnapshot(): Promise<ResourceSnapshot> {
    return { sampledAt: Date.now() };
  }

  async getLastResourceSnapshot(): Promise<{ snapshot: ResourceSnapshot | null }> {
    return { snapshot: null };
  }

  async claimLaunchReport(): Promise<{ firstLaunch: boolean }> {
    return { firstLaunch: true };
  }
}
